REQUIREMENTS = 'pandas>=1.5\nopenpyxl>=3.0\n'

def _decode(b):
    return gzip.decompress(base64.b64decode(b)).decode("utf-8")

def _install():
    """Register the inlined modules under their real dotted names.

    Real names matter: the modules' own `from credit_suite... import ...`
    statements then resolve against sys.modules instead of the filesystem, so
    nothing had to be rewritten to travel -- the code that ships is the code
    that was tested.
    """
    for name in _ORDER:
        module = types.ModuleType(name)
        module.__file__ = name.replace(".", "/") + ".py"
        if name in _PACKAGES:
            module.__path__ = []
            module.__package__ = name
        else:
            module.__package__ = name.rpartition(".")[0]
        sys.modules[name] = module
    for name in _ORDER:
        parent, _, leaf = name.rpartition(".")
        if parent:
            setattr(sys.modules[parent], leaf, sys.modules[name])
    for name in _ORDER:
        exec(compile(_decode(_SRC[name]), sys.modules[name].__file__, "exec"),
             sys.modules[name].__dict__)


def _write(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)

def main():
    cwd = os.getcwd()
    # The files the refresh and fallback flows need, first.
    _write(os.path.join(cwd, "runner.py"), _decode(RUNNER_B64))
    _write(os.path.join(cwd, "macro.bas"), _decode(MACRO_B64))
    _write(os.path.join(cwd, "requirements.txt"), REQUIREMENTS)
    _install()
    base = os.path.join(cwd, "Bank_Peer_Monitor_fallback.xlsx")
    out = os.path.join(cwd, "Bank_Peer_Monitor.xlsm")
    layout = sys.modules['credit_suite.sources.fdic.layout']
    runner = sys.modules['credit_suite.sources.fdic.runner']
    package = sys.modules['credit_suite.engine.package']
    layout.build(base, code_py=_decode(RUNNER_B64),
                 code_vba=_decode(MACRO_B64))
    package.assemble(base, out, os.path.join(cwd, 'macro.bas'),
                     'PeerMonitor')
    from datetime import date
    asof = date.fromisoformat('2026-03-31')
    runner.run(out, demo=True, asof=asof)
    runner.run(base, demo=True, asof=asof)
    print("Built:", out)
    print("Fallback (no VBA):", base)
    print("Also wrote runner.py, macro.bas, requirements.txt in", cwd)

if __name__ == '__main__':
    try:
        main()
    except ImportError as exc:
        sys.stderr.write("Missing dependency: %s\n"
                         "Run: python -m pip install pandas openpyxl\n" % exc)
        sys.exit(1)
